import os, re

rlm_session_dir = os.environ.get('RLM_SESSION_DIR', '')
print(f"RLM_SESSION_DIR: {rlm_session_dir}")

# Load any grids from session logs
if rlm_session_dir:
    session_file = rlm_session_dir + '/../../sessions/' + os.path.basename(rlm_session_dir) + '.jsonl'
    if os.path.exists(session_file):
        with open(session_file, 'r') as f:
            content = f.read()

        # Look for demo pairs and test input
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        grid_content = {}
        current_key = None
        current_h, current_w = 0, 0

        for line in content.split('\n'):
            match = re.match(pattern, line)
            if match:
                current_key, current_h, current_w = match.groups()[1], int(match.group(2)), int(match.group(3))
            elif current_key and current_h > 0 and current_w > 0:
                parts = line.split()
                if parts and parts[0].isdigit():
                    row = [int(x) for x in parts]
                    if len(row) == current_w:
                        grid_content[current_key] = grid_content.get(current_key, []) + [row]

        for key in sorted(grid_content.keys()):
            print(f"Grid {key}: {len(grid_content[key])}x{current_w}")
            print(grid_content[key])
    else:
        print(f"No session file at {session_file}")
else:
    print("RLM_SESSION_DIR not set")

